{
  "title": "进水与猜疑",
  "synopsis": "广播站突发断电，维修员林岚与主持人周野在排查中从互相猜疑到默契配合，确认了线路进水的故障原因。",
  "preview_blurb": "老街广播站突发断电，维修员林岚与主持人周野在狭窄的接线盒前，用万用表与手电筒寻找恢复声音的线索。",
  "scenes": [
    {
      "title": "突发断电与争执",
      "location": "老街广播站操作间",
      "dramatic_goal": "展现断电突发状况，确立两人初期的理念摩擦与猜疑。",
      "lines": [
        {
          "kind": "sfx",
          "text": "刺耳的麦克风电流啸叫声骤然响起，紧接着啪的一声闷响，广播站陷入死寂。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "哎！怎么又没声了？这破设备是不是成心跟我作对？老街坊可都等着听下午的评书呢！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "让开。这是硬件故障，别乱拍操作台，越拍越坏。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "我拍怎么了？昨天还好好的，肯定是有人嫌吵，恶意剪线！"
        }
      ]
    },
    {
      "title": "排查外墙接线盒",
      "location": "广播站外墙",
      "dramatic_goal": "通过万用表数据排除人为破坏，两人在拆卸螺丝中初步建立配合。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "剪线？万用表测出短路，阻值趋近于零。听这连续的滴滴声，是线路进水，不是人为破坏。拿上手电，跟我去外墙接线盒。"
        },
        {
          "kind": "sfx",
          "text": "万用表发出连续的滴滴声，伴随工具碰撞声。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "行行行，我帮你拿工具……哎哟！差点砸了脚。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "别碰剥线钳！你只负责打手电，光束对准那个生锈的十字螺丝。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "知道了。林岚，街坊们听不到广播会急坏的，张奶奶还等我的天气提示出门买菜呢。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "逆时针拧。我知道他们急，但安全是底线。稳住手电，别晃，对，就照这儿。"
        }
      ]
    },
    {
      "title": "默契配合与惊雷悬念",
      "location": "外墙接线盒前",
      "dramatic_goal": "完成初步接线，确立敲铃约定，并用惊雷引出主线缆暗伤的新波折。",
      "lines": [
        {
          "kind": "sfx",
          "text": "螺丝掉落，接线盒盖打开的摩擦声。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "果然，旧电源接头绝缘层严重老化，里面全进水了。我得悬空重新接线，角度太偏，手有点够不到。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "我帮你托着手臂，你借我的力。这高度行吗？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "嗯，保持住别抖。递一下防水胶带。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "给。等彻底修好了，我敲三声老铜铃给街坊们报平安，这主意行不行？他们肯定高兴。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "行，前提是必须通过绝缘测试。"
        },
        {
          "kind": "sfx",
          "text": "窗外突然传来一声震耳的惊雷。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "等等……主线缆可能还有暗伤。"
        }
      ]
